<?php require __DIR__.'/../config/app.php';$root=realpath(__DIR__.'/../../data/ingest');if(!$root){exit('No ingest directory.');}$files=glob($root.'/*.json');$count=0;foreach($files as $file){$payload=json_decode(file_get_contents($file),true);foreach(($payload['stocks']??[]) as $s){q('INSERT INTO stocks(symbol,name,exchange,sector,industry,market_cap,pe,eps,dividend_yield,beta,revenue_growth,eps_growth,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),exchange=VALUES(exchange),sector=VALUES(sector),industry=VALUES(industry),market_cap=VALUES(market_cap),pe=VALUES(pe),eps=VALUES(eps),dividend_yield=VALUES(dividend_yield),beta=VALUES(beta),revenue_growth=VALUES(revenue_growth),eps_growth=VALUES(eps_growth),updated_at=VALUES(updated_at)',[$s['symbol'],$s['name']??null,$s['exchange']??null,$s['sector']??null,$s['industry']??null,$s['market_cap']??null,$s['pe']??null,$s['eps']??null,$s['dividend_yield']??null,$s['beta']??null,$s['revenue_growth']??null,$s['eps_growth']??null,$s['updated_at']??date('Y-m-d H:i:s')]);$count++;}foreach(($payload['prices']??[]) as $p){q('INSERT IGNORE INTO prices(symbol,ts,open,high,low,close,volume) VALUES(?,?,?,?,?,?,?)',[$p['symbol'],$p['ts'],$p['open']??null,$p['high']??null,$p['low']??null,$p['close']??null,$p['volume']??null]);}}echo 'Imported '.$count.' stock records.';